import{_ as e,o as s,c as a,d as l}from"./app-jL2-PcE8.js";const n={},o=l(`<h1 id="definir-todos-los-estilos-de-lista-en-una-sola-declaracion" tabindex="-1"><a class="header-anchor" href="#definir-todos-los-estilos-de-lista-en-una-sola-declaracion"><span>Definir todos los estilos de lista en una sola declaración</span></a></h1><p>La propiedad <code>list-style</code> en CSS es una propiedad abreviada que permite definir todos los estilos de lista en una sola declaración. Esta propiedad combina tres propiedades individuales:</p><ul><li><p><strong>list-style-type</strong>: Define el tipo de marcador de lista (por ejemplo, círculo, cuadrado, número, etc.).</p></li><li><p><strong>list-style-position</strong>: Especifica la posición de los marcadores de lista (dentro o fuera del contenido del elemento de la lista).</p></li><li><p><strong>list-style-image</strong>: Permite usar una imagen personalizada como marcador de lista.</p></li></ul><h2 id="ejemplo-de-uso" tabindex="-1"><a class="header-anchor" href="#ejemplo-de-uso"><span>Ejemplo de uso</span></a></h2><div class="language-css line-numbers-mode" data-ext="css" data-title="css"><pre class="language-css"><code><span class="token selector">ul</span> <span class="token punctuation">{</span>
  <span class="token property">list-style</span><span class="token punctuation">:</span> square inside <span class="token url"><span class="token function">url</span><span class="token punctuation">(</span><span class="token string url">&#39;mi_imagen.png&#39;</span><span class="token punctuation">)</span></span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>En este ejemplo:</p><ul><li><p><code>list-style-type: square;</code> define que los marcadores serán cuadrados.</p></li><li><p><code>list-style-position: inside;</code> coloca los marcadores dentro del contenido del elemento de la lista.</p></li><li><p><code>list-style-image: url(&#39;mi_imagen.png&#39;);</code> usa una imagen personalizada como marcador.</p></li></ul><h2 id="valores-predeterminados" tabindex="-1"><a class="header-anchor" href="#valores-predeterminados"><span>Valores predeterminados</span></a></h2><p>Si no se especifica algún valor, se usarán los valores predeterminados:</p><ul><li><p><code>list-style-type: disc;</code> (círculo relleno).</p></li><li><p><code>list-style-position: outside;</code> (fuera del contenido del elemento de la lista).</p></li><li><p><code>list-style-image: none;</code> (sin imagen).</p></li></ul>`,10),i=[o];function t(d,r){return s(),a("div",null,i)}const p=e(n,[["render",t],["__file","list-style.html.vue"]]),u=JSON.parse('{"path":"/css/listas/list-style.html","title":"Definir todos los estilos de lista en una sola declaración","lang":"en-US","frontmatter":{},"headers":[{"level":2,"title":"Ejemplo de uso","slug":"ejemplo-de-uso","link":"#ejemplo-de-uso","children":[]},{"level":2,"title":"Valores predeterminados","slug":"valores-predeterminados","link":"#valores-predeterminados","children":[]}],"git":{"updatedTime":null,"contributors":[]},"filePathRelative":"css/listas/list-style.md"}');export{p as comp,u as data};
